           //$(this).css('font-size', (curFont + step) + 'px');
           $(this).css('font-size', '18' + 'px');
       });
   }
 
   function changeFontSizedec(element, step) {
       step = parseInt(step, 10);
       var el = $('p,li,ul,button,div,a,h1,h2,h5,table,label,textarea,select,input,radio,checkbox,h4:not("#eNag")');
       $.each(el, function () {
           var curFont = parseInt($(this).css('font-size'));
           //$(this).css('font-size', (curFont + step) + 'px');
           $(this).css('font-size', '10' + 'px');
       });
   }
 
   function resetFontSize(element) {
       var el = $('p,li,ul,button,div,a,h1,h2,h4,h5,table,textarea,placeholder,label,select,radio,checkbox,a:not("#serv"),input:not("#serv")');
       $.each(el, function () {
           $(this).css('font-size', '10px');
       });
